package com.paperterritory.app
import android.graphics.Color;import okhttp3.*;import org.json.JSONObject;import java.util.concurrent.TimeUnit
data class PlayerState(val id:String,val name:String,val x:Float,val y:Float,val color:Int,val area:Int,val alive:Boolean,val kills:Int,val trail:List<Pair<Float,Float>>)
data class GameState(val width:Int,val height:Int,val players:List<PlayerState>,val selfId:String,val cells:Map<String,String>,val room:String,val mode:String,val targetPercent:Int)
class NetworkClient{private val client=OkHttpClient.Builder().pingInterval(15,TimeUnit.SECONDS).build();private var socket:WebSocket?=null
var serverUrl="wss://YOUR-RENDER-SERVICE.onrender.com"
fun connect(name:String,room:String,privateRoom:Boolean,mode:String,character:String,onState:(GameState)->Unit,onError:(String)->Unit,onMatchEnd:(String)->Unit={}){socket=client.newWebSocket(Request.Builder().url(serverUrl).build(),object:WebSocketListener(){override fun onFailure(w:WebSocket,t:Throwable,r:Response?){onError("Unable to connect to the multiplayer server.")};override fun onMessage(w:WebSocket,text:String){try{val o=JSONObject(text);if(o.optString("type")=="match_end"){onMatchEnd(o.optString("winnerId"));return};if(o.optString("type")=="error"){onError(o.optString("message","Server error."));return};if(o.getString("type")!="state")return;val ps=mutableListOf<PlayerState>();val a=o.getJSONArray("players");for(i in 0 until a.length()){val p=a.getJSONObject(i);val tr=mutableListOf<Pair<Float,Float>>();val ta=p.getJSONArray("trail");for(j in 0 until ta.length()){val q=ta.getJSONArray(j);tr+=q.getDouble(0).toFloat() to q.getDouble(1).toFloat()};ps+=PlayerState(p.getString("id"),p.getString("name"),p.getDouble("x").toFloat(),p.getDouble("y").toFloat(),Color.rgb(p.getInt("r"),p.getInt("g"),p.getInt("b")),p.getInt("area"),p.getBoolean("alive"),p.optInt("kills",0),tr)};val cells=mutableMapOf<String,String>();val ca=o.getJSONObject("cells");ca.keys().forEach{k->cells[k]=ca.getString(k)};onState(GameState(o.getInt("width"),o.getInt("height"),ps,o.getString("selfId"),cells,o.optString("room",""),o.optString("mode","standard"),o.optInt("targetPercent",100)))}catch(_:Exception){}}});socket?.send(JSONObject().apply{put("type","join");put("name",name);put("room",room);put("private",privateRoom);put("mode",mode);put("character",character)}.toString())}
fun direction(x:Float,y:Float){socket?.send(JSONObject().apply{put("type","move");put("dx",x);put("dy",y)}.toString())}}